function settleNativePrimarySale(PrimarySale calldata sale)
        external
        payable
        returns (bytes32 settlementKey, bytes32 profileId, address wallet);

function settleERC20PrimarySale(PrimarySale calldata sale, address asset)
        external
        returns (bytes32 settlementKey, bytes32 profileId, address wallet);

function officialSettled(bytes32 revenueClass, bytes32 profileId, address wallet, address asset)
        external
        view
        returns (uint256);

function resolvedPrimaryPolicyHash(
        bytes32 revenueClass,
        uint256 collectionId,
        uint256 tokenId,
        bytes32 templateId,
        bytes32 profileId,
        address wallet,
        bytes32 assignmentHash
    ) external view returns (bytes32);

function isAuthorizedRecordWriter(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordType,
        address actor,
        bytes calldata authorizationData
    ) external view returns (bool);

records.summary:
@notice Returns whether `actor` currently controls the named record write.
 @dev Direct calls need no detached signature: `actor == msg.sender` at the host.
      Relayed typed-write surfaces can pass a nonempty `authorizationData` payload.

